// @name To-do
// @background #f1f5f9
// @refresh 3600
// A to-do list for a touch screen. Tap a circle to tick a to-do off, its text
// to edit it (the keyboard comes up), the bin to delete it (it asks first),
// and add your own at the bottom. The list scrolls, and it is kept.
//
// Reminders: a time typed with a to-do ("milk at 5", "call mum tomorrow at
// 9:30", "pills in 20 minutes") is its due time, and the bell beside a row
// sets or moves one. The frame wakes for the next one, chimes once on its
// buzzer where it has one (frameos.tone) and shows the to-do as due until it
// is ticked off or moved.
import { dueLabel, isDue, nextAt, parseWhen, ringing, secondsToNext } from './when'

const SAMPLE = [
  { text: 'Water the plants', done: true },
  { text: 'Call grandma about Sunday', done: false },
  { text: 'Book the dentist', done: false },
  { text: 'Oat milk, coffee beans, lemons', done: false },
  { text: 'Take the recycling out', done: false },
  { text: 'Fix the bike light', done: false },
]

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-slate-100 text-slate-800',
    muted: 'text-slate-500',
    card: 'bg-white',
    track: 'bg-slate-200',
    fill: 'bg-emerald-500',
    box: 'border-2 border-slate-300',
    boxOn: 'bg-emerald-500',
    doneText: 'text-slate-400',
    field: 'bg-white focus:bg-sky-50',
    add: 'bg-sky-600 text-white active:bg-sky-700',
    cancel: 'bg-slate-200 text-slate-700 active:bg-slate-300',
    remove: 'bg-rose-600 text-white active:bg-rose-700',
    bin: 'text-slate-400',
    // A reminder: still to come, come (due), and the chips that move it.
    chip: 'bg-slate-100 text-slate-600',
    chipDue: 'bg-amber-500 text-white',
    when: 'bg-slate-200 text-slate-700 active:bg-slate-300',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white border-2 border-black',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    box: 'border-4 border-black',
    boxOn: 'bg-black',
    doneText: 'text-black',
    field: 'bg-white',
    add: 'bg-black text-white',
    cancel: 'bg-white text-black border-2 border-black',
    remove: 'bg-black text-white',
    bin: 'text-black',
    chip: 'bg-white text-black border-2 border-black',
    chipDue: 'bg-black text-white',
    when: 'bg-white text-black border-2 border-black',
  },
}

// Colour e-paper (Spectra's six inks): the high-contrast page with the ticks
// and the buttons in solid inks, as the panel shows them (dither.nim's
// measured table), so nothing is dithered into confetti.
THEMES.inks = {
  ...THEMES.high,
  fill: 'bg-[#2a5531]',
  boxOn: 'bg-[#2a5531]',
  add: 'bg-[#18539a] text-white',
  remove: 'bg-[#6b1119] text-white',
  chipDue: 'bg-[#6b1119] text-white',
}

const themeOf = (app) => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

// A panel of 900 px or more on its shorter side at render scale 1 (a 13.3"
// colour e-paper, 1200 px) draws everything that much larger (K), by halves:
// S() turns Tailwind's sizes in a class list into pixels times K, so the
// list, its rows and the new to-do fill the panel. Elsewhere K is 1 and the
// classes stay as they are.
let K = 1
const TEXT = { xs: [12, 16], sm: [14, 20], base: [16, 24], lg: [18, 28], xl: [20, 28], '2xl': [24, 32], '3xl': [30, 36], '4xl': [36, 40] }
const RADII = { lg: 8, xl: 12, '2xl': 16 }
const S = (cls) => (K === 1 ? cls : cls.split(' ').map((c) => {
  let m = /^text-(xs|sm|base|lg|xl|2xl|3xl|4xl)$/.exec(c)
  if (m) return `text-[${Math.round(TEXT[m[1]][0] * K)}px] leading-[${Math.round(TEXT[m[1]][1] * K)}px]`
  m = /^rounded-(lg|xl|2xl)$/.exec(c)
  if (m) return `rounded-[${Math.round(RADII[m[1]] * K)}px]`
  m = /^border-(\d+)$/.exec(c)
  if (m) return `border-${Math.round(Number(m[1]) * K)}`
  m = /^(h|w|p|px|py|pl|pr|pt|pb|gap)-(\d+)$/.exec(c)
  if (m) return `${m[1]}-[${Math.round(Number(m[2]) * 4 * K)}px]`
  return c
}).join(' '))

// The list itself: scene state, kept on disk (the `todos` field), so it
// outlasts a restart. The first version kept only which samples were ticked.
const load = (app) => {
  const kept = app.state.todos
  if (Array.isArray(kept)) return kept
  const ticked = frameos.recall('done')
  return SAMPLE.map((item, i) => ({ text: item.text, done: Array.isArray(ticked) ? !!ticked[i] : item.done }))
}
const save = (todos) => frameos.setState('todos', todos)

// The scene's settings: whether a reminder makes a sound, and the clock the
// times are written in.
const soundOn = (app) => String(app.state.sound ?? 'true') !== 'false'
const twelveHour = (app) => app.state.clock === '12'

// What a tap on a row changes: its tick, its text, its reminder (when, and
// whether it has come) and whether it asks to be deleted or is being given a
// time, a signal each, and the tally; and what is typed into the new to-do.
// They are signals: a tap runs only the rows, the tally and the field that read
// them, not get(). A tap that adds or deletes a row sets none (the list changes
// shape), so get() draws the list again.
let todos = []
const rows = []
const row = (i) => (rows[i] ??= {
  done: signal(false), text: signal(''), asking: signal(false),
  due: signal(0), come: signal(false), timing: signal(false),
})
const doneCount = signal(0)
const dueCount = signal(0)
const total = signal(0)
const draft = signal('')
// The day it is, so a row's "Tomorrow 9:00" reads "9:00" once it is today.
const today = signal(0)
const show = () => {
  const asking = frameos.recall('asking') ?? -1
  const timing = frameos.recall('timing') ?? -1
  const now = Date.now()
  todos.forEach((item, i) => {
    const r = row(i)
    r.done.value = item.done
    r.text.value = item.text
    r.asking.value = asking === i
    r.due.value = typeof item.due === 'number' ? item.due : 0
    r.come.value = isDue(item, now)
    r.timing.value = timing === i
  })
  doneCount.value = todos.filter((item) => item.done).length
  dueCount.value = todos.filter((item) => isDue(item, now)).length
  total.value = todos.length
  draft.value = frameos.recall('draft') || ''
  const day = new Date(now)
  today.value = new Date(day.getFullYear(), day.getMonth(), day.getDate()).getTime()
}
const change = (i, patch) => {
  todos = todos.map((other, j) => (j === i ? { ...other, ...patch } : other))
  save(todos)
  show()
}
const ask = (i) => {
  frameos.remember('asking', i)
  // The reminder bar goes with it: no signal set, so a whole get() draws the
  // add row back in its place.
  if ((frameos.recall('timing') ?? -1) >= 0) {
    frameos.remember('timing', -1)
    return
  }
  show()
}
const remove = (i) => {
  todos = todos.filter((_, j) => j !== i)
  save(todos)
  frameos.remember('asking', -1)
  frameos.remember('timing', -1)
}
const add = () => {
  const said = (frameos.recall('draft') || '').trim()
  if (!said) return
  // "milk at 5": the to-do "milk", due at five.
  const { text, due } = parseWhen(said, new Date())
  const item = { text, done: false }
  if (due !== null) {
    item.due = due
    // A time already gone is shown as due, never rung for.
    if (due <= Date.now()) item.rang = true
  }
  todos = [...todos, item]
  save(todos)
  frameos.remember('draft', '')
}

// A row's reminder: the bar that gives it a time takes the place of the add
// row at the bottom, where nothing scrolls it away. Opening and closing it
// set no signal, so get() lays the page out again around it.
const timeFor = (i) => {
  frameos.remember('timing', i)
  frameos.remember('asking', -1)
}
const remindAt = (i, due) => change(i, { due, rang: false })
// Later by so many minutes than it was, or than now when it has come.
const later = (i, minutes) => remindAt(i, Math.max(todos[i]?.due ?? 0, Date.now()) + minutes * 60 * 1000)
const noReminder = (i) => change(i, { due: undefined, rang: undefined })

const Check = () => (
  <svg className={S('w-5 h-5 text-white')} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5 12l5 5L20 7" />
  </svg>
)

const Bin = ({ className }) => (
  <svg className={S(`w-6 h-6 ${className}`)} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M4 7h16M10 11v6M14 11v6M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2l1-12M9 7V4h6v3" />
  </svg>
)

const Bell = ({ className, size = 'w-6 h-6' }) => (
  <svg className={S(`${size} ${className}`)} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9M10.3 21a1.94 1.94 0 0 0 3.4 0" />
  </svg>
)

const Tally = memo(({ t, small }) => (
  <span className={S(`${small ? 'text-base' : 'text-lg'} ${t.muted}`)}>
    {total.value
      ? `${doneCount.value} of ${total.value} done${dueCount.value ? `, ${dueCount.value} due` : ''}`
      : 'Nothing to do'}
  </span>
))

const Progress = memo(({ t, small }) => (
  <div className={S(`${small ? 'h-2' : 'h-3'} rounded-full ${t.track}`)}>
    <div className={`h-full rounded-full ${t.fill} w-[${total.value ? (doneCount.value * 100) / total.value : 0}%]`} />
  </div>
))

// A choice in a row being given a time.
const WhenChip = ({ t, small, strong = false, onClick, children }) => (
  <div className={S(`${small ? 'h-8 px-2 text-sm' : 'h-10 px-3 text-base'} rounded-xl flex items-center ${strong ? `font-bold ${t.add}` : t.when}`)}
    onClick={onClick}>
    {children}
  </div>
)

// The bar of the row being given a time: what it is and when, and the times
// to pick. Each pick moves the reminder and keeps the bar; Done closes it.
const WhenBar = memo(({ i, t, small, twelve }) => {
  const r = rows[i]
  const now = new Date(Math.max(Date.now(), today.value))
  const due = r.due.value
  const morning = nextAt(now.getTime(), 9)
  const evening = nextAt(now.getTime(), 18)
  return (
    <div className={S(`flex flex-col ${small ? 'gap-1' : 'gap-2'}`)}>
      <div className={S(`flex items-center ${small ? 'gap-1' : 'gap-2'}`)}>
        <Bell className={t.muted} size={small ? 'w-5 h-5' : 'w-6 h-6'} />
        <span className={S(`flex-1 min-w-0 ${small ? 'text-base' : 'text-lg'} truncate`)}>
          {due ? `${dueLabel(due, now, twelve)}: ${r.text.value}` : `Remind me: ${r.text.value}`}
        </span>
      </div>
      <div className={S(`flex flex-wrap ${small ? 'gap-1' : 'gap-2'}`)}>
        <WhenChip t={t} small={small} onClick={() => later(i, 15)}>+15 min</WhenChip>
        <WhenChip t={t} small={small} onClick={() => later(i, 60)}>+1 hour</WhenChip>
        <WhenChip t={t} small={small} onClick={() => remindAt(i, evening)}>{dueLabel(evening, now, twelve)}</WhenChip>
        <WhenChip t={t} small={small} onClick={() => remindAt(i, morning)}>{dueLabel(morning, now, twelve)}</WhenChip>
        {due ? <WhenChip t={t} small={small} onClick={() => noReminder(i)}>No reminder</WhenChip> : null}
        <WhenChip t={t} small={small} strong onClick={() => timeFor(-1)}>Done</WhenChip>
      </div>
    </div>
  )
})

// `small`: a watch, a 2.8" LCD, the 4.2" and 5.79" e-paper or a small
// circle, where every pixel of the row's width goes to the to-do's words
// (and a row with no reminder has no bell: a time typed with it gives one).
const Row = memo(({ i, t, small, twelve }) => {
  const r = rows[i]
  const done = r.done.value
  const text = r.text.value
  const due = r.due.value
  const words = small ? 'text-base' : 'text-lg'
  // The row the reminder bar is about shows its bell lit.
  const picked = r.timing.value
  const label = due ? dueLabel(due, new Date(Math.max(Date.now(), today.value)), twelve, true) : ''
  return r.asking.value ? (
    <div className={S(`flex items-center ${small ? 'gap-2 rounded-xl px-2 py-2' : 'gap-3 rounded-2xl px-4 py-3'} ${t.card}`)}>
      <span className={S(`flex-1 ${words} truncate`)}>{`Delete "${text}"?`}</span>
      <div className={S(`${small ? 'px-2 py-1' : 'px-4 py-2'} rounded-xl ${words} ${t.cancel}`)} onClick={() => ask(-1)}>
        Cancel
      </div>
      <div className={S(`${small ? 'px-2 py-1' : 'px-4 py-2'} rounded-xl ${words} font-bold ${t.remove}`)} onClick={() => remove(i)}>
        Delete
      </div>
    </div>
  ) : (
    <div className={S(`flex items-center ${small ? 'gap-2 rounded-xl pl-2 pr-1 py-1' : 'gap-3 rounded-2xl pl-4 pr-2 py-2'} ${t.card}`)}>
      <div className={S(`${small ? 'w-7 h-7' : 'w-8 h-8'} shrink-0 rounded-full flex items-center justify-center ${done ? t.boxOn : t.box}`)}
        title={done ? 'Mark not done' : 'Mark done'}
        onClick={() => change(i, { done: !done })}>
        {done ? <Check /> : null}
      </div>
      <input className={S(`flex-1 min-w-0 ${small ? 'h-9 px-1' : 'h-11 px-2'} rounded-lg ${words} ${t.field} ${done ? t.doneText : ''}`)}
        value={text}
        onChange={(e) => change(i, { text: e.target.value })} />
      {due ? (
        <div className={S(`${small ? 'h-7 px-1 gap-1 text-xs' : 'h-8 px-2 gap-1 text-sm'} shrink-0 flex items-center rounded-lg ${picked ? t.add : r.come.value ? `font-bold ${t.chipDue}` : t.chip}`)}
          title={`Reminder ${label}`}
          onClick={() => timeFor(i)}>
          <Bell className="" size={small ? 'w-3 h-3' : 'w-4 h-4'} />
          <span>{label}</span>
        </div>
      ) : small ? null : (
        <div className={S(`w-9 h-11 shrink-0 flex items-center justify-center rounded-xl ${picked ? t.add : ''}`)}
          title="Set a reminder"
          onClick={() => timeFor(i)}>
          <Bell className={picked ? '' : t.bin} />
        </div>
      )}
      <div className={S(`${small ? 'w-8 h-9' : 'w-11 h-11'} shrink-0 flex items-center justify-center rounded-xl`)}
        title="Delete"
        onClick={() => ask(i)}>
        <Bin className={t.bin} />
      </div>
    </div>
  )
})

// What is typed into the new to-do: the app's own, kept between renders (an
// ESP32 starts each with a fresh module).
const Draft = memo(({ t, small }) => (
  <input className={S(`flex-1 min-w-0 ${small ? 'h-10 px-3 text-base' : 'h-12 px-4 text-lg'} rounded-xl ${t.card} ${t.field}`)}
    value={draft.value} placeholder="Add a to-do"
    onChange={(e) => { frameos.remember('draft', e.target.value); draft.value = e.target.value }}
    onKeyDown={(e) => { if (e.key === 'Enter') add() }} />
))

// On a round panel the progress is a ring along the rim, filling clockwise
// from the top.
const RoundProgress = memo(({ W, H, t }) => {
  const cx = W / 2, cy = H / 2, rr = Math.min(W, H) / 2 - 5
  const share = total.value ? doneCount.value / total.value : 0
  const high = t !== THEMES.color
  const a = share * 2 * Math.PI
  const x = (cx + rr * Math.sin(a)).toFixed(1), y = (cy - rr * Math.cos(a)).toFixed(1)
  const arc = share >= 1
    ? `M ${cx} ${cy - rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy + rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy - rr}`
    : `M ${cx} ${cy - rr} A ${rr} ${rr} 0 ${share > 0.5 ? 1 : 0} 1 ${x} ${y}`
  return (
    <svg className={`absolute left-0 top-0 w-[${W}px] h-[${H}px]`} viewBox={`0 0 ${W} ${H}`} fill="none" strokeWidth={8} strokeLinecap="round">
      <circle cx={cx} cy={cy} r={rr} stroke={high ? '#ffffff' : '#e2e8f0'} />
      {share > 0 ? <path d={arc} stroke={high ? '#000000' : '#10b981'} /> : null}
    </svg>
  )
})

// The title and the tally in the arc at the top, the list as wide as the
// circle lets it be, the new to-do in the arc at the bottom.
const roundList = (t, W, H, twelve, picking) => {
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12
  const chord = (dy) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  // A small circle (the 1.46") takes the smaller type, the compact rows and
  // a head measured from its type, so the tally never slips under the list.
  const small = R < 200
  const headTop = Math.round(R * 0.92)
  const headH = small ? 32 + 24 : 36 + 28
  const headW = chord(headTop)
  const listTop = Math.min(Math.round(R * 0.61), headTop - headH - 6)
  // The new to-do's row as low as its chord still holds the field and the
  // button side by side.
  const addH = small ? 40 : 44
  const addWant = small ? 210 : 250
  const addBottom = Math.min(Math.round(R * 0.58) + 10 + addH, Math.floor(Math.sqrt(Math.max(0, R * R - (addWant / 2) ** 2))))
  const addTop = addBottom - addH
  const listBottom = addTop - 10
  const listW = Math.min(chord(listTop), chord(listBottom))
  const addW = chord(addBottom)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <RoundProgress W={W} H={H} t={t} />
      <div className={`absolute left-[${Math.round(cx - headW / 2)}px] top-[${Math.round(cy - headTop)}px] w-[${headW}px] flex flex-col items-center`}>
        <span className={`${small ? 'text-2xl' : 'text-3xl'} font-bold`}>Today</span>
        <Tally t={t} small={small} />
      </div>
      <div className={`absolute left-[${Math.round(cx - listW / 2)}px] top-[${Math.round(cy - listTop)}px] w-[${listW}px] h-[${listTop + listBottom}px] overflow-y-auto`}>
        {picking >= 0 ? (
          <WhenBar i={picking} t={t} small={small} twelve={twelve} />
        ) : (
          <div className="flex flex-col gap-2">
            {todos.map((_, i) => <Row i={i} t={t} small={small} twelve={twelve} />)}
          </div>
        )}
      </div>
      <div className={`absolute left-[${Math.round(cx - addW / 2)}px] top-[${Math.round(cy + addTop)}px] w-[${addW}px] h-[${addH}px] flex items-center gap-2`}>
        <Draft t={t} small={small} />
        <div className={`${small ? 'h-10 px-3 text-base' : 'h-11 px-4 text-lg'} rounded-xl flex items-center font-bold ${t.add}`} onClick={add}>
          Add
        </div>
      </div>
    </div>
  )
}

// The frame's Back keeps a to-do that asked to be deleted, as its Cancel
// does, and closes a row being given a time, as its Done does; else it is the
// frame's.
export function onEvent(app, context) {
  if (context.event !== 'back') return false
  if ((frameos.recall('asking') ?? -1) < 0 && (frameos.recall('timing') ?? -1) < 0) return false
  if (!todos.length) todos = load(app)
  ask(-1)
  return true
}

// A reminder that has come: rung once (the frame's chime, where it has a
// buzzer and the scene's Reminder sound is on), then shown as due until it is
// ticked off or given another time.
const ring = (app, now) => {
  const { ring, sound } = ringing(todos, now)
  if (ring.length === 0) return
  todos = todos.map((item, i) => (ring.includes(i) ? { ...item, rang: true } : item))
  save(todos)
  if (sound && soundOn(app) && typeof frameos.tone === 'function') frameos.tone()
}

export function get(app, context) {
  const t = themeOf(app)
  const twelve = twelveHour(app)
  todos = load(app)
  const now = Date.now()
  ring(app, now)
  // Wake for the next reminder, within the hour the scene draws again anyway.
  const wait = secondsToNext(todos, now, 3600)
  if (wait > 0) frameos.setNextSleep(wait)
  show()
  K = 1
  // The row being given a time, if any: its bar replaces the add row.
  const timing = frameos.recall('timing') ?? -1
  const picking = timing >= 0 && timing < todos.length ? timing : -1
  if (context?.round === true) return roundList(t, context.imageWidth, context.imageHeight, twelve, picking)
  // A watch, a 2.8" LCD or a small e-paper: less padding, smaller type, the
  // rows' words wider.
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const small = Math.min(W, H) < 320
  K = Math.min(W, H) >= 900 ? Math.min(3, Math.floor((Math.min(W, H) / 480) * 2) / 2) : 1
  // The list's box holds whole rows: what is around it is of known height
  // (Tailwind's: text-4xl's line is 40 px, h-12 48, ...), and so is a row
  // (an input of h-11 or h-9 in its padding, a border on e-paper), so no
  // row shows cut in half above the new to-do. It still gives way (min-h-0)
  // when the frame's keyboard takes the bottom of the panel.
  const k = (n) => Math.round(n * K)
  const pad = k(small ? 12 : 24)
  const gap = k(small ? 8 : 12)
  const border = t === THEMES.color ? 0 : 2 * k(2)
  const headH = k(small ? 36 : 40)
  const barH = k(small ? 8 : 12)
  const addH = k(small ? 40 : 48)
  const rowH = k(small ? 44 : 60) + border
  const rowGap = k(8)
  const room = H - 2 * pad - headH - barH - addH - 3 * gap
  const fit = Math.max(1, Math.floor((room + rowGap) / (rowH + rowGap)))
  // With the reminder bar (taller than the add row, its chips wrapping as
  // the width asks) the list takes what is left.
  const boxH = picking < 0 && todos.length > fit ? fit * rowH + (fit - 1) * rowGap : 0
  return (
    <div className={S(`flex flex-col w-full h-full ${small ? 'gap-2 p-3' : 'gap-3 p-6'} ${t.page}`)}>
      <div className="flex items-end justify-between">
        <span className={S(`${small ? 'text-3xl' : 'text-4xl'} font-bold`)}>Today</span>
        <Tally t={t} small={small} />
      </div>
      <Progress t={t} small={small} />
      <div className="flex-1 min-h-0 flex flex-col">
        <div className={`${boxH ? `h-[${boxH}px] min-h-0` : 'flex-1 min-h-0'} overflow-y-auto`}>
          <div className={S('flex flex-col gap-2')}>
            {todos.map((_, i) => <Row i={i} t={t} small={small} twelve={twelve} />)}
          </div>
        </div>
      </div>
      {picking >= 0 ? (
        <WhenBar i={picking} t={t} small={small} twelve={twelve} />
      ) : (
        <div className={S(`flex items-center ${small ? 'gap-2' : 'gap-3'}`)}>
          <Draft t={t} small={small} />
          <div className={S(`${small ? 'h-10 px-4 text-base' : 'h-12 px-5 text-lg'} rounded-xl flex items-center font-bold ${t.add}`)} onClick={add}>
            Add
          </div>
        </div>
      )}
    </div>
  )
}

