// When a to-do is due: a time said with it ("milk at 5", "call mum tomorrow
// at 9:30", "pills in 20 minutes", "bins tonight", "dentist on friday at 2pm"),
// its label, and which to-dos are due now. A due time is a moment
// (milliseconds since 1970), read and shown in the frame's time zone.

const MINUTE = 60 * 1000
const DAY = 24 * 60 * MINUTE

// A to-do woken for a little early still rings: a frame's clock and its
// sleep timer are not to the second.
export const EARLY_MS = 30 * 1000
// A reminder missed by more than this (the frame was off) is marked as
// rung without a sound: nobody wants yesterday's bins at three in the night.
export const LATE_MS = 60 * MINUTE

const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat']

const at = (day: Date, hour: number, minute: number) =>
  new Date(day.getFullYear(), day.getMonth(), day.getDate(), hour, minute, 0, 0)
const plusDays = (day: Date, days: number) => new Date(day.getFullYear(), day.getMonth(), day.getDate() + days)

// The hour said without am or pm: 1 to 6 is the afternoon (nobody sets a
// to-do for four in the night by saying "at 4"), 7 to 11 the next of the two
// when no day is said and the morning when one is, 12 noon.
function hourOf(hour: number, meridiem: string | null, minute: number, day: Date | null, now: Date, evening: boolean): number[] {
  if (meridiem === 'am') return [hour % 12]
  if (meridiem === 'pm') return [(hour % 12) + 12]
  if (hour > 12 || hour === 0) return [hour]
  if (hour === 12) return [12]
  if (evening || hour <= 6) return [hour + 12]
  if (day) return [hour]
  // Today: the morning if it is still ahead, else the evening.
  return at(now, hour, minute).getTime() > now.getTime() ? [hour] : [hour + 12, hour]
}

/** The words of a to-do and the moment they name, if any: "milk at 5" is
 * { text: "milk", due: today at 17:00 } (tomorrow when that is past). A time
 * needs its "at" ("at 5", "at 17:30"), unless it says am or pm ("5pm") or
 * has a colon ("17:30"), so "buy 5 apples" stays as it is. */
export function parseWhen(input: string, now: Date = new Date()): { text: string; due: number | null } {
  const said = String(input || '').trim()
  let text = ' ' + said + ' '
  const take = (re: RegExp): RegExpExecArray | null => {
    const m = re.exec(text)
    if (m) text = text.slice(0, m.index) + ' ' + text.slice(m.index + m[0].length)
    return m
  }

  // "in 20 minutes", "in an hour", "in half an hour", "in 1.5 hours"
  const rel = take(/\s(?:in|after)\s+(half an?|an?|one|\d+(?:[.,]\d+)?)\s*(?:(minutes?|mins?|m)|(hours?|hrs?|h))(?=[\s,.!?])/i)
  if (rel) {
    const amount = /^half/i.test(rel[1]) ? 0.5 : /^(an?|one)$/i.test(rel[1]) ? 1 : Number(rel[1].replace(',', '.'))
    const minutes = rel[3] ? amount * 60 : amount
    if (minutes > 0 && minutes <= 7 * 24 * 60) {
      return { text: words(text, said), due: now.getTime() + Math.round(minutes * MINUTE) }
    }
    return { text: said, due: null }
  }

  let day: Date | null = null
  let evening = false
  let defaultHour = 9
  const word = take(/\s(today|tonight|this evening|tomorrow|tmrw)(?=[\s,.!?])/i)
  if (word) {
    const w = word[1].toLowerCase()
    if (w === 'tomorrow' || w === 'tmrw') day = plusDays(now, 1)
    else day = plusDays(now, 0)
    if (w === 'tonight' || w === 'this evening') {
      evening = true
      defaultHour = 20
    }
  }
  // A day by its whole name only: "sun cream" and "sat nav" name no day.
  let weekday = -1
  const named = word
    ? null
    : take(/\s(?:on\s+)?(?:next\s+)?(monday|tuesday|wednesday|thursday|friday|saturday|sunday)(?=[\s,.!?])/i)
  if (named) weekday = WEEKDAYS.indexOf(named[1].slice(0, 3).toLowerCase())

  let hour = -1
  let minute = 0
  let meridiem: string | null = null
  const clock =
    take(/\s(?:at|@|by)\s*(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?(?:\s*o'?clock)?(?=[\s,.!?])/i) ||
    take(/\s(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?m\.?|p\.?m\.?)(?=[\s,.!?])/i) ||
    take(/\s(\d{1,2}):(\d{2})()(?=[\s,.!?])/i)
  if (clock) {
    hour = Number(clock[1])
    minute = clock[2] ? Number(clock[2]) : 0
    meridiem = clock[3] ? (clock[3][0].toLowerCase() === 'a' ? 'am' : 'pm') : null
    if (hour > 23 || minute > 59 || (meridiem && (hour === 0 || hour > 12))) return { text: said, due: null }
  } else {
    const noon = take(/\s(?:at\s+)?(noon|midday|midnight)(?=[\s,.!?])/i)
    if (noon) hour = noon[1].toLowerCase() === 'midnight' ? 0 : 12
  }

  if (hour < 0 && !word && weekday < 0) return { text: said, due: null }

  if (weekday >= 0) {
    let ahead = (weekday - now.getDay() + 7) % 7
    day = plusDays(now, ahead)
    if (ahead === 0) {
      const h = hour < 0 ? defaultHour : hourOf(hour, meridiem, minute, day, now, evening)[0]
      if (at(day, h, minute).getTime() <= now.getTime()) day = plusDays(now, 7)
    }
  }
  const base = day ?? now
  const hours = hour < 0 ? [defaultHour] : hourOf(hour, meridiem, minute, day, now, evening)
  let due = at(base, hours[0], minute)
  if (!day && due.getTime() <= now.getTime()) {
    // No day said and the time is past today: the next one of them.
    const later = hours.slice(1).map((h) => at(now, h, minute)).find((d) => d.getTime() > now.getTime())
    due = later ?? at(plusDays(now, 1), hours[hours.length - 1], minute)
  }
  return { text: words(text, said), due: due.getTime() }
}

// What is left of the words: the spaces one, no "at" or comma dangling, and
// no "remind me to" in front of what to do.
function tidy(text: string): string {
  return text
    .replace(/\s+/g, ' ')
    .replace(/^\s*(?:please\s+)?(?:remind me to|remind me|don't forget to|do not forget to)\s+/i, '')
    .replace(/(?:\s(?:at|on|by|@|in|for|-|–))+\s*$/i, '')
    .replace(/^[\s,;:.–-]+|[\s,;:–-]+$/g, '')
    .trim()
}

// The words left, or all that was said when nothing is ("at 5"), with a
// capital letter in front where it had one ("Remind me to pay rent" is "Pay
// rent").
function words(text: string, said: string): string {
  const left = tidy(text)
  if (!left) return said
  const first = said[0]
  return first && first !== first.toLowerCase() ? left[0].toUpperCase() + left.slice(1) : left
}

const pad = (n: number) => String(n).padStart(2, '0')

/** "17:00", or "5:00 pm" on a 12-hour clock. */
export function timeLabel(when: Date, twelve: boolean): string {
  const h = when.getHours()
  const m = pad(when.getMinutes())
  return twelve ? `${h % 12 || 12}:${m} ${h < 12 ? 'am' : 'pm'}` : `${h}:${m}`
}

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

/** A due time as short as it can be read: "17:00" today, "Tomorrow 9:00",
 * "Fri 9:00" within the week, "3 Dec" further off, and "Yesterday 17:00"
 * or "Mon 17:00" for one gone by. `short` leaves out "Tomorrow" and
 * "Yesterday" for a weekday, for a row with little room. */
export function dueLabel(due: number, now: Date, twelve: boolean, short = false): string {
  const when = new Date(due)
  const days = Math.round((plusDays(when, 0).getTime() - plusDays(now, 0).getTime()) / DAY)
  const time = timeLabel(when, twelve)
  if (days === 0) return time
  if (days === 1 && !short) return `Tomorrow ${time}`
  if (days === -1 && !short) return `Yesterday ${time}`
  if (days > -7 && days < 7) return `${DAY_NAMES[when.getDay()]} ${time}`
  return `${when.getDate()} ${MONTHS[when.getMonth()]}`
}

type Todo = { text: string; done: boolean; due?: number; rang?: boolean }

/** Whether a to-do's reminder has come and not been answered: it shows as due. */
export const isDue = (item: Todo, now: number) => !item.done && typeof item.due === 'number' && item.due <= now + EARLY_MS

/** The to-dos to ring for now, and whether any is recent enough to make a
 * sound for (LATE_MS): each is rung once, then kept as rung. */
export function ringing(todos: Todo[], now: number): { ring: number[]; sound: boolean } {
  const ring: number[] = []
  let sound = false
  todos.forEach((item, i) => {
    if (item.rang || !isDue(item, now)) return
    ring.push(i)
    if (now - (item.due as number) < LATE_MS) sound = true
  })
  return { ring, sound }
}

/** Seconds until the next reminder still to ring, at most `cap`; -1 when
 * there is none, and the scene's own interval holds. */
export function secondsToNext(todos: Todo[], now: number, cap: number): number {
  let next = Infinity
  for (const item of todos) {
    if (item.done || item.rang || typeof item.due !== 'number') continue
    if (item.due > now + EARLY_MS) next = Math.min(next, item.due)
  }
  if (next === Infinity) return -1
  return Math.min(cap, Math.max(1, Math.ceil((next - now) / 1000)))
}

/** The next whole hour from `from` that is at least 15 minutes ahead: where
 * a new reminder starts. */
export function nextHour(from: number): number {
  const d = new Date(from + 15 * MINUTE)
  return new Date(d.getFullYear(), d.getMonth(), d.getDate(), d.getHours() + 1, 0, 0, 0).getTime()
}

/** The same clock time on the next day it is still ahead: "tomorrow at 9"
 * when 9:00 has gone, today when it has not. */
export function nextAt(from: number, hour: number): number {
  const now = new Date(from)
  const today = at(now, hour, 0)
  return today.getTime() > from ? today.getTime() : at(plusDays(now, 1), hour, 0).getTime()
}

