import { get } from './app'
import { dueLabel, nextAt, parseWhen, secondsToNext } from './when'

// Tuesday 12 March 2024, 14:40 in the zone the test runs in.
const now = new Date(2024, 2, 12, 14, 40, 0)
const on = (day: number, hour: number, minute = 0) => new Date(2024, 2, day, hour, minute, 0).getTime()
const MINUTE = 60 * 1000

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

describe('a time said with a to-do', () => {
  it('takes "at 5" as five in the afternoon, today or tomorrow', () => {
    expect(parseWhen('Milk at 5', now)).toEqual({ text: 'Milk', due: on(12, 17) })
    expect(parseWhen('milk at 5pm', now)).toEqual({ text: 'milk', due: on(12, 17) })
    expect(parseWhen('milk at 2', now)).toEqual({ text: 'milk', due: on(13, 14) })
    expect(parseWhen('Pay rent at 5:30 p.m.', now)).toEqual({ text: 'Pay rent', due: on(12, 17, 30) })
    expect(parseWhen('Remind me to pay rent at 5', now)).toEqual({ text: 'Pay rent', due: on(12, 17) })
  })

  it('takes a morning hour as the next of the two, and as the morning on a day said', () => {
    expect(parseWhen('call the vet at 8', now)).toEqual({ text: 'call the vet', due: on(12, 20) })
    expect(parseWhen('call mum tomorrow at 9:30', now)).toEqual({ text: 'call mum', due: on(13, 9, 30) })
    expect(parseWhen('standup at 10am', now)).toEqual({ text: 'standup', due: on(13, 10) })
  })

  it('reads a clock time, noon, a day, tonight and "in so long"', () => {
    expect(parseWhen('meeting 17:30', now)).toEqual({ text: 'meeting', due: on(12, 17, 30) })
    expect(parseWhen('lunch with Ana at noon', now)).toEqual({ text: 'lunch with Ana', due: on(13, 12) })
    expect(parseWhen('dentist on Friday at 2pm', now)).toEqual({ text: 'dentist', due: on(15, 14) })
    expect(parseWhen('bins tonight', now)).toEqual({ text: 'bins', due: on(12, 20) })
    expect(parseWhen('pills in 20 minutes', now)).toEqual({ text: 'pills', due: now.getTime() + 20 * MINUTE })
    expect(parseWhen('check the oven in half an hour', now)).toEqual({ text: 'check the oven', due: now.getTime() + 30 * MINUTE })
    expect(parseWhen('water plants tuesday', now)).toEqual({ text: 'water plants', due: on(19, 9) })
  })

  it('leaves alone what names no time', () => {
    expect(parseWhen('buy 5 apples', now)).toEqual({ text: 'buy 5 apples', due: null })
    expect(parseWhen('sun cream', now)).toEqual({ text: 'sun cream', due: null })
    expect(parseWhen("tomorrow's lunch", now)).toEqual({ text: "tomorrow's lunch", due: null })
    expect(parseWhen('meet at 25', now)).toEqual({ text: 'meet at 25', due: null })
    // A time and nothing else keeps its words.
    expect(parseWhen('at 5', now)).toEqual({ text: 'at 5', due: on(12, 17) })
  })
})

describe('a due time on the screen', () => {
  it('is as short as it can be read', () => {
    expect(dueLabel(on(12, 17), now, false)).toBe('17:00')
    expect(dueLabel(on(12, 17), now, true)).toBe('5:00 pm')
    expect(dueLabel(on(13, 9), now, false)).toBe('Tomorrow 9:00')
    expect(dueLabel(on(13, 9), now, false, true)).toBe('Wed 9:00')
    expect(dueLabel(on(11, 17), now, false)).toBe('Yesterday 17:00')
    expect(dueLabel(new Date(2024, 3, 3, 9).getTime(), now, false)).toBe('3 Apr')
  })

  it('offers the next nine and six o\'clock', () => {
    expect(nextAt(now.getTime(), 9)).toBe(on(13, 9))
    expect(nextAt(now.getTime(), 18)).toBe(on(12, 18))
  })
})

describe('reminders', () => {
  it('chimes once when one comes, and keeps it as rung', () => {
    const tone = mock.tone(() => true)
    const app = makeApp({ state: { todos: [{ text: 'Milk', done: false, due: on(12, 14, 39) }, { text: 'Bread', done: false }] } })
    at(now.getTime(), () => get(app, makeContext()))
    expect(tone).toHaveBeenCalledTimes(1)
    expect(app.state.todos[0]).toMatchObject({ text: 'Milk', rang: true })
    expect(app.state.todos[1].rang).toBeUndefined()
    // The renders after it (a tap, the hour) make no sound.
    at(now.getTime() + MINUTE, () => get(app, makeContext()))
    expect(tone).toHaveBeenCalledTimes(1)
  })

  it('wakes the frame for the next one, within the hour', () => {
    mock.tone(() => true)
    const soon = makeApp({ state: { todos: [{ text: 'Milk', done: false, due: on(12, 14, 50) }] } })
    at(now.getTime(), () => get(soon, makeContext()))
    expect(soon.nextSleep).toBe(600)
    const later = makeApp({ state: { todos: [{ text: 'Milk', done: false, due: on(12, 20) }] } })
    at(now.getTime(), () => get(later, makeContext()))
    expect(later.nextSleep).toBe(3600)
    // Done, or rung already: nothing to wake for.
    expect(secondsToNext([{ text: 'a', done: true, due: on(12, 15) }, { text: 'b', done: false, due: on(12, 15), rang: true }], now.getTime(), 3600)).toBe(-1)
  })

  it('stays quiet when its sound is off, and for one missed by hours', () => {
    const tone = mock.tone(() => true)
    const quiet = makeApp({ state: { sound: 'false', todos: [{ text: 'Milk', done: false, due: on(12, 14, 39) }] } })
    at(now.getTime(), () => get(quiet, makeContext()))
    const missed = makeApp({ state: { todos: [{ text: 'Bins', done: false, due: on(12, 9) }] } })
    at(now.getTime(), () => get(missed, makeContext()))
    expect(tone).toHaveBeenCalledTimes(0)
    expect(quiet.state.todos[0].rang).toBe(true)
    expect(missed.state.todos[0].rang).toBe(true)
  })
})
